{
  "API_calls": [],
  "collected_information": {
    "python_version": ">= 3.10 (tested on 3.10, 3.11, 3.12)",
    "installation": {
      "from_pypi": "pip install agentscope",
      "from_source": [
        "git clone -b main https://github.com/agentscope-ai/agentscope.git",
        "cd agentscope",
        "pip install -e ."
      ],
      "development_install": "pip install -e .[dev]"
    },
    "dependencies": {
      "core": {
        "mcp": ">=1.13",
        "opentelemetry-api": ">=1.39.0",
        "qdrant-client": "==1.15.1"
      },
      "development_extras": [
        "pytest",
        "pytest-forked",
        "fakeredis",
        "aiosqlite",
        "greenlet"
      ],
      "build_system": {
        "setuptools": ">=45",
        "wheel": ""
      }
    },
    "environment_variables": [
      "DASHSCOPE_API_KEY",
      "GAODE_API_KEY"
    ],
    "test_execution": {
      "framework": "pytest",
      "commands": [
        "pytest tests",
        "coverage run -m pytest tests",
        "coverage report -m"
      ],
      "individual_test_files": "pytest tests/model_anthropic_test.py (inferred)"
    },
    "ci_details": {
      "os": ["ubuntu-latest", "windows-latest", "macos-15"],
      "python_versions": ["3.10", "3.11", "3.12"],
      "setup_python_action": "actions/setup-python@master",
      "explicit_packages": [
        "setuptools==78.1.1",
        "wheel==0.45.1",
        "coverage",
        "pytest"
      ]
    },
    "notes": {
      "pre_commit_hooks": {
        "optional_for_code_quality": true,
        "commands": [
          "pip install pre-commit",
          "pre-commit install",
          "pre-commit run --all-files"
        ]
      },
      "no_additional_os_packages_required": true,
      "environment_variables_required_for_tests": "not explicitly stated",
      "no_explicit_individual_test_commands_in_docs": true
    },
    "sources": [
      "README.md",
      "CONTRIBUTING.md",
      "pyproject.toml",
      ".github/workflows/unittest.yml"
    ]
  },
  "terminate": true
}
